# SPDX-License-Identifier: MIT
# What the logger measures, at a pace set by a timer of the Cortex-M4 (machine.Timer): the CPU's
# temperature from Linux (/sys/class/thermal), the voltage on A0 and the chip's internal reference
# from the M4's ADC. Each expiry takes a sample and queues it; the GUI writes and draws them.
# In the LVGL MPY Studio simulator the samples are made up, at the same pace.

import time

try:
    import machine
    import mpy_m4

    HARDWARE = mpy_m4.available()
except ImportError:
    HARDWARE = False

THERMAL = "/sys/class/thermal/thermal_zone0/temp"
FIELDS = ["time", "cpu_c", "a0_v", "vref_v"]


def _cpu_celsius():
    with open(THERMAL) as f:
        return int(f.read()) / 1000


class Board:
    def __init__(self):
        self.queue = []
        self._timer = None
        self._a0 = machine.ADC("A0")
        self._vref = machine.ADC(machine.ADC.CORE_VREF)

    def _sample(self, timer):
        try:
            self.queue.append((time.localtime(), _cpu_celsius(), self._a0.read_uv() / 1e6,
                               self._vref.read_uv() / 1e6))
        except OSError:
            pass  # a sample lost; the next one comes on time

    def start(self, seconds):
        self.stop()
        self._timer = machine.Timer(-1, period=seconds * 1000, callback=self._sample)

    def stop(self):
        if self._timer is not None:
            self._timer.deinit()
            self._timer = None

    def poll(self):
        pass


class Simulated:
    def __init__(self):
        self.queue = []
        self._period = 0
        self._next = 0
        self._n = 0

    def start(self, seconds):
        self._period = seconds * 1000
        self._next = time.ticks_add(time.ticks_ms(), self._period)

    def stop(self):
        self._period = 0

    def poll(self):
        if self._period and time.ticks_diff(time.ticks_ms(), self._next) >= 0:
            self._next = time.ticks_add(self._next, self._period)
            self._n += 1
            wave = (self._n % 40) / 40
            self.queue.append((time.localtime(), 41 + 6 * wave, 1.2 + 0.8 * (1 - wave), 1.208))


sensors = Board() if HARDWARE else Simulated()

# SPDX-License-Identifier: MIT
# The log as a CSV file on the board (logs/ in MicroPython's folder, /usr/local/mpy/fs/logs), one
# row a sample, with the date and time of the board's clock (set by NTP once online). In the
# simulator the rows stay in memory.

import os

from sensors import FIELDS, HARDWARE

FOLDER = "logs"


def _stamp(t):
    return "%04d-%02d-%02d %02d:%02d:%02d" % t[:6]


class Log:
    def __init__(self):
        self.path = None
        self.rows = 0
        self.size = 0
        self._memory = []

    def new(self, t):
        name = "log-%04d%02d%02d-%02d%02d%02d.csv" % t[:6]
        header = ",".join(FIELDS) + "\n"
        self.rows = 0
        self.size = len(header)
        if HARDWARE:
            try:
                os.mkdir(FOLDER)
            except OSError:
                pass  # it is there
            self.path = FOLDER + "/" + name
            with open(self.path, "w") as f:
                f.write(header)
        else:
            self.path = name
            self._memory = [header]

    def add(self, sample):
        t, cpu, a0, vref = sample
        line = "%s,%.1f,%.4f,%.4f\n" % (_stamp(t), cpu, a0, vref)
        if HARDWARE:
            with open(self.path, "a") as f:
                f.write(line)
        else:
            self._memory.append(line)
        self.rows += 1
        self.size += len(line)

    def read(self):
        if HARDWARE:
            with open(self.path) as f:
                return f.read()
        return "".join(self._memory)


log = Log()
